from opentv.core.discovery import identify_ssdp_device

def make_dial():
    return identify_ssdp_device({'ST': 'urn:dial-multiscreen-org:service:dial:1', 'LOCATION': 'http://192.168.1.50:8008/ssdp/desc.xml'}, '192.168.1.50')

def make_google():
    return identify_ssdp_device({'SERVER': 'Linux UPnP/1.0 Chromecast/1.0', 'ST': 'upnp:rootdevice'}, '192.168.1.50')

def aggregate(devices):
    devices_by_ip = {}
    for device in devices:
        ip = device.ip
        if ip not in devices_by_ip:
            devices_by_ip[ip] = device
        else:
            existing = devices_by_ip[ip]
            if (existing.model.startswith('Unknown') or existing.model.startswith('Smart TV')) and not (device.model.startswith('Unknown') or device.model.startswith('Smart TV')):
                existing.model = device.model
            elif existing.model.startswith('Unknown') and not device.model.startswith('Unknown'):
                existing.model = device.model

            android_types = {'android_tv', 'google_tv', 'fire_tv'}
            if existing.device_type in ('unknown', 'smart_tv') and device.device_type in android_types:
                existing.device_type = device.device_type
            elif existing.device_type == 'unknown' and device.device_type != 'unknown':
                existing.device_type = device.device_type

            existing.raw_info.setdefault('additional_responses', []).append(device.raw_info)
    return list(devices_by_ip.values())

# Order 1: DIAL then Google TV
r1 = aggregate([make_dial(), make_google()])[0]
print('Order 1 (DIAL then Google):', r1.device_type, r1.model)
assert r1.device_type == 'google_tv'
assert 'Chromecast' in r1.model

# Order 2: Google TV then DIAL
r2 = aggregate([make_google(), make_dial()])[0]
print('Order 2 (Google then DIAL):', r2.device_type, r2.model)
assert r2.device_type == 'google_tv'
assert 'Chromecast' in r2.model

print('PERFECT SYMMETRY VERIFIED!')
"

